function n(r){const t=Number(r||0);return new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",maximumFractionDigits:0}).format(Number.isFinite(t)?t:0)}function i(r,t=1){const e=Number(r||0);return Number.isFinite(e)?`${e.toFixed(t)}%`:"0%"}function u(r){if(!r)return"-";const t=new Date(r);return Number.isNaN(t.getTime())?String(r):t.toLocaleString("en-IN",{day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"})}export{i as a,u as b,n as f};
